import javax.xml.bind.JAXBException;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CriaProcEventoGenericoTests {

    private ConfiguracoesNfe config;
    private TEnvEvento enviEvento;
    private TRetEvento retorno;

    @Before
    public void setUp() {
        // Mock configuration
        config = mock(ConfiguracoesNfe.class);
        when(config.getEncode()).thenReturn(StandardCharsets.UTF_8);
        when(config.getAmbiente()).thenReturn(AmbienteEnum.HOMOLOGACAO);
        when(config.getEstado()).thenReturn(EstadosEnum.GO);

        // Mock TEnvEvento
        enviEvento = mock(TEnvEvento.class);

        // Mock TRetEvento
        retorno = mock(TRetEvento.class);
    }

    @Test
    public void testCriaProcEventoGenerico_Success() throws Exception {
        try (MockedStatic<XmlNfeUtil> mockedXmlNfeUtil = mockStatic(XmlNfeUtil.class);
             MockedStatic<Assinar> mockedAssinar = mockStatic(Assinar.class)) {

            // Arrange
            String xmlEvento = "<evento v=\"1.0\"><infEvento></infEvento></evento>";
            String xmlAssinado = "<evento xmlns=\"http://www.portalfiscal.inf.br/nfe\" v=\"1.0\"><infEvento></infEvento></evento>";

            mockedXmlNfeUtil.when(() -> XmlNfeUtil.objectToXml(enviEvento, StandardCharsets.UTF_8)).thenReturn(xmlEvento);
            mockedAssinar.when(() -> Assinar.assinaNfe(any(), anyString(), any())).thenReturn(xmlAssinado);

            TEnvEvento eventoAssinado = mock(TEnvEvento.class);
            TEvento evento = mock(TEvento.class);
            mockedXmlNfeUtil.when(() -> XmlNfeUtil.xmlToObject(xmlAssinado, TEnvEvento.class)).thenReturn(eventoAssinado);
            when(eventoAssinado.getEvento()).thenReturn(java.util.Arrays.asList(evento));

            TProcEvento procEventoResult = mock(TProcEvento.class);
            mockedXmlNfeUtil.when(() -> XmlNfeUtil.objectToXml(procEventoResult, StandardCharsets.UTF_8)).thenReturn("<procEvento></procEvento>");

            // Act
            String result = EventoGenericoUtil.criaProcEventoGenerico(config, enviEvento, retorno);

            // Assert
            assertNotNull(result);
            assertEquals("<procEvento></procEvento>", result);
        }
    }

    @Test(expected = JAXBException.class)
    public void testCriaProcEventoGenerico_JAXBException() throws Exception {
        try (MockedStatic<XmlNfeUtil> mockedXmlNfeUtil = mockStatic(XmlNfeUtil.class)) {
            // Arrange
            mockedXmlNfeUtil.when(() -> XmlNfeUtil.objectToXml(enviEvento, StandardCharsets.UTF_8)).thenThrow(new JAXBException("Error"));

            // Act
            EventoGenericoUtil.criaProcEventoGenerico(config, enviEvento, retorno);
        }
    }

    @Test(expected = NfeException.class)
    public void testCriaProcEventoGenerico_NfeException() throws Exception {
        try (MockedStatic<XmlNfeUtil> mockedXmlNfeUtil = mockStatic(XmlNfeUtil.class);
             MockedStatic<Assinar> mockedAssinar = mockStatic(Assinar.class)) {

            // Arrange
            String xmlEvento = "<evento v=\"1.0\"><infEvento></infEvento></evento>";
            mockedXmlNfeUtil.when(() -> XmlNfeUtil.objectToXml(enviEvento, StandardCharsets.UTF_8)).thenReturn(xmlEvento);
            mockedAssinar.when(() -> Assinar.assinaNfe(any(), anyString(), any())).thenThrow(new NfeException("Error"));

            // Act
            EventoGenericoUtil.criaProcEventoGenerico(config, enviEvento, retorno);
        }
    }
}

