            String xmlAssinado = "<envEvento xmlns=\"http://www.portalfiscal.inf.br/nfe\" versao=\"1.00\"></envEvento>";
            assinarMock.when(() -> Assinar.assinaNfe(any(), anyString(), any()))
                    .thenReturn(xmlAssinado);

