    @Test
    public void testMontaCCeMultipleEvents() throws NfeException {
        for (int i = 0; i < 5; i++) {
            Evento e = new Evento();
            e.setChave("12345678901234567890123456789012345678901234");
            e.setSequencia(i+1);
            e.setMotivo("Correção "+i);
            e.setCnpj("12345678000195");
            e.setDataEvento(java.time.LocalDateTime.now());
            listaCCe.add(e);
        }

        try (MockedStatic<XmlNfeUtil> xmlNfeUtilMockedStatic = mockStatic(XmlNfeUtil.class)) {
            xmlNfeUtilMockedStatic.when(() -> XmlNfeUtil.dataNfe(any(), any())).thenReturn("2023-10-10T10:10:10-03:00");

