    @Test
    public void testMontaCCeEventIdGeneration() throws NfeException {
        listaCCe.add(evento);

        try (MockedStatic<XmlNfeUtil> xmlNfeUtilMockedStatic = mockStatic(XmlNfeUtil.class);
             MockedStatic<ChaveUtil> chaveUtilMockedStatic = mockStatic(ChaveUtil.class)) {

            xmlNfeUtilMockedStatic.when(() -> XmlNfeUtil.dataNfe(any(), any())).thenReturn("2023-10-10T10:10:10-03:00");
            chaveUtilMockedStatic.when(() -> ChaveUtil.completarComZerosAEsquerda(anyString(), anyInt())).thenReturn("01");

