package br.com.swconsultoria.nfe;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

import java.util.HashMap;
import java.util.Map;
import java.util.ArrayList;
import java.util.List;

public class GenerateReportTests {

    private ConsultaTributacao.ValidationReport report;

    @Before
    public void setUp() {
        report = new ConsultaTributacao().new ValidationReport();
    }

    @Test
    public void testGenerateReportWithNoIssues() {
        report.arrayDetected = false;
        report.arraySize = 0;
        report.extraFields = new ArrayList<>();
        report.missingFields = new ArrayList<>();
        report.typeErrors = new HashMap<>();
        report.strictConversionSuccess = true;
        report.strictConversionError = null;

        String result = report.generateReport();
        assertTrue(result.contains("=== RELATORIO DE VALIDACAO ==="));
        assertTrue(result.contains("ESTRUTURA 100% COMPATIVEL"));
        assertTrue(result.contains("Nenhum campo extra no JSON"));
        assertTrue(result.contains("Nenhum campo faltando"));
        assertTrue(result.contains("Todos os tipos estao corretos"));
        assertTrue(result.contains("Conversao estrita: SUCESSO"));
    }

    @Test
    public void testGenerateReportWithArrayDetected() {
        report.arrayDetected = true;
        report.arraySize = 5;
        report.extraFields = new ArrayList<>();
        report.missingFields = new ArrayList<>();
        report.typeErrors = new HashMap<>();
        report.strictConversionSuccess = true;
        report.strictConversionError = null;

        String result = report.generateReport();
        assertTrue(result.contains("Array detectado com 5 elemento(s)"));
        assertTrue(result.contains("Validacao realizada no primeiro elemento"));
    }

    @Test
    public void testGenerateReportWithExtraFields() {
        report.arrayDetected = false;
        report.arraySize = 0;
        report.extraFields = new ArrayList<>();
        report.extraFields.add("field1");
        report.extraFields.add("field2");
        report.missingFields = new ArrayList<>();
        report.typeErrors = new HashMap<>();
        report.strictConversionSuccess = true;
        report.strictConversionError = null;

        String result = report.generateReport();
        assertTrue(result.contains("ATENCAO: Campos EXTRAS no JSON (nao mapeados no DTO):"));
        assertTrue(result.contains("  - field1"));
        assertTrue(result.contains("  - field2"));
    }

    @Test
    public void testGenerateReportWithMissingFields() {
        report.arrayDetected = false;
        report.arraySize = 0;
        report.extraFields = new ArrayList<>();
        report.missingFields = new ArrayList<>();
        report.missingFields.add("requiredField1");
        report.missingFields.add("requiredField2");
        report.typeErrors = new HashMap<>();
        report.strictConversionSuccess = false;
        report.strictConversionError = "Missing required fields";

        String result = report.generateReport();
        assertTrue(result.contains("ATENCAO: Campos FALTANDO no JSON (esperados no DTO):"));
        assertTrue(result.contains("  - requiredField1"));
        assertTrue(result.contains("  - requiredField2"));
        assertTrue(result.contains("Conversao estrita: FALHOU"));
        assertTrue(result.contains("  Erro: Missing required fields"));
    }

    @Test
    public void testGenerateReportWithTypeErrors() {
        report.arrayDetected = false;
        report.arraySize = 0;
        report.extraFields = new ArrayList<>();
        report.missingFields = new ArrayList<>();
        report.typeErrors = new HashMap<>();
        report.typeErrors.put("field1", "Expected String but got Integer");
        report.typeErrors.put("field2", "Expected Boolean but got String");
        report.strictConversionSuccess = true;
        report.strictConversionError = null;

        String result = report.generateReport();
        assertTrue(result.contains("ERRO: Incompatibilidade de tipos:"));
        assertTrue(result.contains("  - field1: Expected String but got Integer"));
        assertTrue(result.contains("  - field2: Expected Boolean but got String"));
    }

    @Test
    public void testGenerateReportWithAllIssues() {
        report.arrayDetected = true;
        report.arraySize = 3;
        report.extraFields = new ArrayList<>();
        report.extraFields.add("extra1");
        report.missingFields = new ArrayList<>();
        report.missingFields.add("missing1");
        report.typeErrors = new HashMap<>();
        report.typeErrors.put("typeError1", "Expected String but got Integer");
        report.strictConversionSuccess = false;
        report.strictConversionError = "Type mismatch error";

        String result = report.generateReport();
        assertTrue(result.contains("Array detectado com 3 elemento(s)"));
        assertTrue(result.contains("ATENCAO: Campos EXTRAS no JSON"));
        assertTrue(result.contains("  - extra1"));
        assertTrue(result.contains("ATENCAO: Campos FALTANDO no JSON"));
        assertTrue(result.contains("  - missing1"));
        assertTrue(result.contains("ERRO: Incompatibilidade de tipos:"));
        assertTrue(result.contains("  - typeError1: Expected String but got Integer"));
        assertTrue(result.contains("Conversao estrita: FALHOU"));
        assertTrue(result.contains("  Erro: Type mismatch error"));
    }
}

