package br.com.swconsultoria.nfe;

import com.fasterxml.jackson.core.type.TypeReference;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.MockedStatic;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class GetTests {

    private br.com.swconsultoria.nfe.dom.ConfiguracoesNfe configuracoesNfe;
    private Map<String, String> queryParams;
    private TypeReference<TestResponse> typeRef;

    @Before
    public void setUp() {
        configuracoesNfe = mock(br.com.swconsultoria.nfe.dom.ConfiguracoesNfe.class);
        queryParams = new HashMap<>();
        queryParams.put("param1", "value1");
        typeRef = new TypeReference<TestResponse>() {};
    }

    @Test
    public void testGet_Success() throws Exception {
        String jsonResponse = "{\"message\":\"success\"}";
        TestResponse expectedResponse = new TestResponse("success");

        try (MockedStatic<ConsultaTributacao> mockedStatic = Mockito.mockStatic(ConsultaTributacao.class)) {
            mockedStatic.when(() -> ConsultaTributacao.getJson(any(br.com.swconsultoria.nfe.dom.ConfiguracoesNfe.class), any(Map.class)))
                    .thenReturn(jsonResponse);
            mockedStatic.when(() -> ConsultaTributacao.convertJsonToObject(anyString(), any(TypeReference.class)))
                    .thenReturn(expectedResponse);

            TestResponse result = ConsultaTributacao.get(configuracoesNfe, queryParams, typeRef);

            assertNotNull(result);
            assertEquals(expectedResponse.getMessage(), result.getMessage());
        }
    }

    @Test
    public void testGet_WithEmptyQueryParams() throws Exception {
        String jsonResponse = "{\"message\":\"empty_params\"}";
        TestResponse expectedResponse = new TestResponse("empty_params");
        Map<String, String> emptyParams = new HashMap<>();

        try (MockedStatic<ConsultaTributacao> mockedStatic = Mockito.mockStatic(ConsultaTributacao.class)) {
            mockedStatic.when(() -> ConsultaTributacao.getJson(any(br.com.swconsultoria.nfe.dom.ConfiguracoesNfe.class), any(Map.class)))
                    .thenReturn(jsonResponse);
            mockedStatic.when(() -> ConsultaTributacao.convertJsonToObject(anyString(), any(TypeReference.class)))
                    .thenReturn(expectedResponse);

            TestResponse result = ConsultaTributacao.get(configuracoesNfe, emptyParams, typeRef);

            assertNotNull(result);
            assertEquals(expectedResponse.getMessage(), result.getMessage());
        }
    }

    @Test
    public void testGet_NullConfig_ThrowsException() throws Exception {
        try (MockedStatic<ConsultaTributacao> mockedStatic = Mockito.mockStatic(ConsultaTributacao.class)) {
            mockedStatic.when(() -> ConsultaTributacao.getJson(any(br.com.swconsultoria.nfe.dom.ConfiguracoesNfe.class), any(Map.class)))
                    .thenThrow(new br.com.swconsultoria.nfe.exception.NfeException("Configuração inválida"));

            assertThrows(br.com.swconsultoria.nfe.exception.NfeException.class, () -> {
                ConsultaTributacao.get(null, queryParams, typeRef);
            });
        }
    }

    @Test
    public void testGet_IOExceptionThrown() throws Exception {
        try (MockedStatic<ConsultaTributacao> mockedStatic = Mockito.mockStatic(ConsultaTributacao.class)) {
            mockedStatic.when(() -> ConsultaTributacao.getJson(any(br.com.swconsultoria.nfe.dom.ConfiguracoesNfe.class), any(Map.class)))
                    .thenThrow(new IOException("Network error"));

            assertThrows(IOException.class, () -> {
                ConsultaTributacao.get(configuracoesNfe, queryParams, typeRef);
            });
        }
    }

    @Test
    public void testGet_NfeExceptionThrown() throws Exception {
        try (MockedStatic<ConsultaTributacao> mockedStatic = Mockito.mockStatic(ConsultaTributacao.class)) {
            mockedStatic.when(() -> ConsultaTributacao.getJson(any(br.com.swconsultoria.nfe.dom.ConfiguracoesNfe.class), any(Map.class)))
                    .thenThrow(new br.com.swconsultoria.nfe.exception.NfeException("NF-e service error"));

            assertThrows(br.com.swconsultoria.nfe.exception.NfeException.class, () -> {
                ConsultaTributacao.get(configuracoesNfe, queryParams, typeRef);
            });
        }
    }

    @Test
    public void testGet_InvalidJsonResponse() throws Exception {
        String invalidJson = "{invalid_json}";

        try (MockedStatic<ConsultaTributacao> mockedStatic = Mockito.mockStatic(ConsultaTributacao.class)) {
            mockedStatic.when(() -> ConsultaTributacao.getJson(any(br.com.swconsultoria.nfe.dom.ConfiguracoesNfe.class), any(Map.class)))
                    .thenReturn(invalidJson);
            mockedStatic.when(() -> ConsultaTributacao.convertJsonToObject(anyString(), any(TypeReference.class)))
                    .thenThrow(new IOException("Invalid JSON format"));

            assertThrows(IOException.class, () -> {
                ConsultaTributacao.get(configuracoesNfe, queryParams, typeRef);
            });
        }
    }

    // Helper class for testing
    static class TestResponse {
        private String message;

        public TestResponse() {}

        public TestResponse(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }

        public void setMessage(String message) {
            this.message = message;
        }
    }
}
